using System.Globalization;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace Slice;

internal static class Program
{
    public static int Main(string[] args)
    {
        return SliceApp.Run(args, Console.Error, Console.OpenStandardOutput());
    }
}

public static class SliceApp
{
    public static int Run(string[] args, TextWriter stderr, Stream outputStream)
    {
        if (!TryParseCommandSequence(args, out var path, out var commands, out var format))
        {
            WriteUsage(stderr);
            return 1;
        }

        try
        {
            ExecuteCommandSequence(path, commands, format, outputStream);

            return 0;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException or InvalidOperationException)
        {
            stderr.WriteLine(ex.Message);
            return 1;
        }
    }

    private static bool TryParseCommandSequence(string[] args, out string path, out List<PipelineCommand> commands, out OutputFormat format)
    {
        path = string.Empty;
        commands = new List<PipelineCommand>();
        format = OutputFormat.Csv;

        if (args.Length < 2)
        {
            return false;
        }

        var filteredArgs = new List<string>(args.Length);
        for (var i = 0; i < args.Length; i++)
        {
            if (IsOption(args[i], "--format"))
            {
                if (i + 1 >= args.Length || !TryParseOutputFormat(args[i + 1], out format))
                {
                    return false;
                }

                i++;
                continue;
            }

            filteredArgs.Add(args[i]);
        }

        if (filteredArgs.Count < 2)
        {
            return false;
        }

        path = filteredArgs[0];
        var index = 1;

        while (index < filteredArgs.Count)
        {
            var token = filteredArgs[index];

            if (IsCommand(token, "select"))
            {
                if (index + 1 >= filteredArgs.Count)
                {
                    return false;
                }

                commands.Add(new PipelineCommand(PipelineCommandKind.Select, filteredArgs[index + 1]));
                index += 2;
            }
            else if (IsCommand(token, "where"))
            {
                if (index + 1 >= filteredArgs.Count)
                {
                    return false;
                }

                var expressionStart = index + 1;
                index = expressionStart;
                while (index < filteredArgs.Count && !IsCommandKeyword(filteredArgs[index]))
                {
                    index++;
                }

                if (index == expressionStart)
                {
                    return false;
                }

                commands.Add(new PipelineCommand(PipelineCommandKind.Where, string.Join(' ', filteredArgs.GetRange(expressionStart, index - expressionStart))));
            }
            else if (IsCommand(token, "sort"))
            {
                if (index + 1 >= filteredArgs.Count)
                {
                    return false;
                }

                var columnName = filteredArgs[index + 1];
                var direction = "asc";
                index += 2;

                if (index < filteredArgs.Count && !IsCommandKeyword(filteredArgs[index]))
                {
                    direction = filteredArgs[index];
                    index++;
                }

                commands.Add(new PipelineCommand(PipelineCommandKind.Sort, columnName, direction));
            }
            else if (IsCommand(token, "head"))
            {
                if (index + 1 >= filteredArgs.Count)
                {
                    return false;
                }

                commands.Add(new PipelineCommand(PipelineCommandKind.Head, filteredArgs[index + 1]));
                index += 2;
            }
            else if (IsCommand(token, "distinct"))
            {
                if (index + 1 >= filteredArgs.Count)
                {
                    return false;
                }

                var columnsStart = index + 1;
                index = columnsStart;
                while (index < filteredArgs.Count && !IsCommandKeyword(filteredArgs[index]))
                {
                    index++;
                }

                if (index == columnsStart)
                {
                    return false;
                }

                commands.Add(new PipelineCommand(PipelineCommandKind.Distinct, string.Join(' ', filteredArgs.GetRange(columnsStart, index - columnsStart))));
            }
            else if (IsCommand(token, "count"))
            {
                commands.Add(new PipelineCommand(PipelineCommandKind.Count));
                index++;
                return index == filteredArgs.Count;
            }
            else if (IsCommand(token, "sum"))
            {
                if (index + 1 >= filteredArgs.Count)
                {
                    return false;
                }

                commands.Add(new PipelineCommand(PipelineCommandKind.Sum, filteredArgs[index + 1]));
                index += 2;
                return index == filteredArgs.Count;
            }
            else if (IsCommand(token, "groupby"))
            {
                if (index + 2 >= filteredArgs.Count)
                {
                    return false;
                }

                var groupColumnName = filteredArgs[index + 1];
                var aggregateName = filteredArgs[index + 2];

                if (IsCommand(aggregateName, "count"))
                {
                    commands.Add(new PipelineCommand(PipelineCommandKind.GroupByCount, groupColumnName));
                    index += 3;
                    return index == filteredArgs.Count;
                }

                if (IsCommand(aggregateName, "sum"))
                {
                    if (index + 3 >= filteredArgs.Count)
                    {
                        return false;
                    }

                    commands.Add(new PipelineCommand(PipelineCommandKind.GroupBySum, groupColumnName, filteredArgs[index + 3]));
                    index += 4;
                    return index == filteredArgs.Count;
                }

                return false;
            }
            else
            {
                return false;
            }
        }

        return commands.Count > 0;
    }

    private static void ExecuteCommandSequence(string path, IReadOnlyList<PipelineCommand> commands, OutputFormat format, Stream outputStream)
    {
        var table = ReadTable(path);

        foreach (var command in commands)
        {
            switch (command.Kind)
            {
                case PipelineCommandKind.Select:
                    table = SelectColumns(table, command.FirstArgument);
                    break;
                case PipelineCommandKind.Where:
                    table = FilterRows(table, command.FirstArgument);
                    break;
                case PipelineCommandKind.Sort:
                    table = SortRows(table, command.FirstArgument, command.SecondArgument ?? "asc");
                    break;
                case PipelineCommandKind.Head:
                    if (!int.TryParse(command.FirstArgument, out var rowCount))
                    {
                        throw new InvalidOperationException("Row count must be a positive integer");
                    }

                    table = HeadRows(table, rowCount);
                    break;
                case PipelineCommandKind.Distinct:
                    table = DistinctRows(table, command.FirstArgument);
                    break;
                case PipelineCommandKind.Count:
                    WriteScalar(table.Rows.Count, format, outputStream);
                    return;
                case PipelineCommandKind.Sum:
                    WriteScalar(CalculateSum(table, command.FirstArgument), format, outputStream);
                    return;
                case PipelineCommandKind.GroupByCount:
                    table = BuildGroupedCountTable(table, command.FirstArgument);
                    break;
                case PipelineCommandKind.GroupBySum:
                    table = BuildGroupedSumTable(table, command.FirstArgument, command.SecondArgument ?? string.Empty);
                    break;
                default:
                    throw new ArgumentOutOfRangeException();
            }
        }

using System.Text;
using Slice;

var tests = new List<(string Name, Action Test)>
{
    ("selects named columns in requested order", SelectsNamedColumnsInRequestedOrder),
    ("returns failure when a selected column is missing", ReturnsFailureWhenSelectedColumnIsMissing),
    ("returns failure when arguments are invalid", ReturnsFailureWhenArgumentsAreInvalid),
    ("renders tabular results as json", RendersTabularResultsAsJson),
    ("renders tabular results as table", RendersTabularResultsAsTable),
    ("renders scalar results as json", RendersScalarResultsAsJson),
    ("filters numeric rows with where", FiltersNumericRowsWithWhere),
    ("filters numeric rows with not-equal where", FiltersNumericRowsWithNotEqualWhere),
    ("filters text rows with where", FiltersTextRowsWithWhere),
    ("returns failure when a where column is missing", ReturnsFailureWhenWhereColumnIsMissing),
    ("returns failure when a where expression is invalid", ReturnsFailureWhenWhereExpressionIsInvalid),
    ("keeps only the first five data rows with head", KeepsOnlyTheFirstFiveDataRowsWithHead),
    ("keeps all rows when head exceeds row count", KeepsAllRowsWhenHeadExceedsRowCount),
    ("returns failure when head row count is not positive", ReturnsFailureWhenHeadRowCountIsNotPositive),
    ("counts all data rows", CountsAllDataRows),
    ("counts remaining rows after filtering", CountsRemainingRowsAfterFiltering),
    ("sums a numeric column", SumsANumericColumn),
    ("returns failure when sum column values are nonnumeric", ReturnsFailureWhenSumColumnValuesAreNonnumeric),
    ("returns failure when sum column is missing", ReturnsFailureWhenSumColumnIsMissing),
    ("groups rows and counts them", GroupsRowsAndCountsThem),
    ("groups rows and sums a numeric column", GroupsRowsAndSumsANumericColumn),
    ("returns failure when a groupby sum column is missing", ReturnsFailureWhenGroupBySumColumnIsMissing),
    ("sorts numeric rows descending", SortsNumericRowsDescending),
    ("sorts rows ascending by default", SortsRowsAscendingByDefault),
    ("sorts text rows descending", SortsTextRowsDescending),
    ("returns failure when a sort column is missing", ReturnsFailureWhenSortColumnIsMissing),
    ("removes duplicate rows for a single distinct column", RemovesDuplicateRowsForASingleDistinctColumn),
    ("removes duplicate rows for multiple distinct columns", RemovesDuplicateRowsForMultipleDistinctColumns),
    ("returns failure when a distinct column is missing", ReturnsFailureWhenDistinctColumnIsMissing),
};

var failures = 0;

foreach (var (name, test) in tests)
{
    try
    {
        test();
        Console.WriteLine($"PASS {name}");
    }
    catch (Exception ex)
    {
        failures++;
        Console.Error.WriteLine($"FAIL {name}: {ex.Message}");
    }
}

return failures == 0 ? 0 : 1;

static void SelectsNamedColumnsInRequestedOrder()
{
    var tempPath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N") + ".csv");
    var originalBytes = Encoding.UTF8.GetBytes("name,age,city\r\nAda,36,London\r\nGrace,47,Paris\r\n");
    File.WriteAllBytes(tempPath, originalBytes);

    try
    {
        using var output = new MemoryStream();
        CsvRoundTripper.WriteSelectedColumns(tempPath, new[] { "name", "age" }, output);

        var result = Encoding.UTF8.GetString(output.ToArray());
        var expected = $"name,age{Environment.NewLine}Ada,36{Environment.NewLine}Grace,47{Environment.NewLine}";
        if (result != expected)
        {
            throw new Exception($"unexpected output: {result}");
        }
    }
    finally
    {
        File.Delete(tempPath);
    }
}

