 38	    private static bool TryParseCommandSequence(string[] args, out string path, out List<PipelineCommand> commands, out OutputFormat format)
 39	    {
 40	        path = string.Empty;
 41	        commands = new List<PipelineCommand>();
 42	        format = OutputFormat.Csv;
 43	
 44	        if (args.Length < 2)
 45	        {
 46	            return false;
 47	        }
 48	
 49	        var filteredArgs = new List<string>(args.Length);
 50	        for (var i = 0; i < args.Length; i++)
 51	        {
 52	            if (IsOption(args[i], "--format"))
 53	            {
 54	                if (i + 1 >= args.Length || !TryParseOutputFormat(args[i + 1], out format))
 55	                {
 56	                    return false;
 57	                }
 58	
 59	                i++;
 60	                continue;
 61	            }
 62	
 63	            filteredArgs.Add(args[i]);
 64	        }
 65	
 66	        if (filteredArgs.Count < 2)
 67	        {
 68	            return false;
 69	        }
 70	
 71	        path = filteredArgs[0];
 72	        var index = 1;
 73	
 74	        while (index < filteredArgs.Count)
 75	        {
 76	            var token = filteredArgs[index];
 77	
 78	            if (IsPipelineSeparator(token))
 79	            {
 80	                index++;
 81	                continue;
 82	            }
 83	
 84	            if (IsCommand(token, "select"))
 85	            {
 86	                if (index + 1 >= filteredArgs.Count)
 87	                {
 88	                    return false;
 89	                }
 90	
 91	                commands.Add(new PipelineCommand(PipelineCommandKind.Select, filteredArgs[index + 1]));
 92	                index += 2;
 93	            }
 94	            else if (IsCommand(token, "where"))
 95	            {
 96	                if (index + 1 >= filteredArgs.Count)
 97	                {
 98	                    return false;
 99	                }
100	
101	                var expressionStart = index + 1;
102	                index = expressionStart;
103	                while (index < filteredArgs.Count && !IsCommandKeyword(filteredArgs[index]) && !IsPipelineSeparator(filteredArgs[index]))
104	                {
105	                    index++;
106	                }
107	
108	                if (index == expressionStart)
109	                {
110	                    return false;
111	                }
112	
113	                commands.Add(new PipelineCommand(PipelineCommandKind.Where, string.Join(' ', filteredArgs.GetRange(expressionStart, index - expressionStart))));
114	            }
115	            else if (IsCommand(token, "sort"))
116	            {
117	                if (index + 1 >= filteredArgs.Count)
118	                {
119	                    return false;
120	                }
121	
122	                var columnName = filteredArgs[index + 1];
123	                var direction = "asc";
124	                index += 2;
125	
126	                if (index < filteredArgs.Count && !IsCommandKeyword(filteredArgs[index]) && !IsPipelineSeparator(filteredArgs[index]))
127	                {
128	                    direction = filteredArgs[index];
129	                    index++;
130	                }
131	
132	                commands.Add(new PipelineCommand(PipelineCommandKind.Sort, columnName, direction));
133	            }
134	            else if (IsCommand(token, "head"))
135	            {
136	                if (index + 1 >= filteredArgs.Count)
137	                {
138	                    return false;
139	                }
140	
141	                commands.Add(new PipelineCommand(PipelineCommandKind.Head, filteredArgs[index + 1]));
142	                index += 2;
143	            }
144	            else if (IsCommand(token, "distinct"))
145	            {
146	                if (index + 1 >= filteredArgs.Count)
147	                {
148	                    return false;
149	                }
150	
151	                var columnsStart = index + 1;
152	                index = columnsStart;
153	                while (index < filteredArgs.Count && !IsCommandKeyword(filteredArgs[index]) && !IsPipelineSeparator(filteredArgs[index]))
154	                {
155	                    index++;
156	                }
157	
158	                if (index == columnsStart)
159	                {
160	                    return false;
161	                }
162	
163	                commands.Add(new PipelineCommand(PipelineCommandKind.Distinct, string.Join(' ', filteredArgs.GetRange(columnsStart, index - columnsStart))));
164	            }
165	            else if (IsCommand(token, "count"))
166	            {
167	                commands.Add(new PipelineCommand(PipelineCommandKind.Count));
168	                index++;
169	            }
170	            else if (IsCommand(token, "sum"))
171	            {
172	                if (index + 1 >= filteredArgs.Count)
173	                {
174	                    return false;
175	                }
176	
177	                commands.Add(new PipelineCommand(PipelineCommandKind.Sum, filteredArgs[index + 1]));
178	                index += 2;
179	            }
180	            else if (IsCommand(token, "groupby"))
181	            {
182	                if (index + 2 >= filteredArgs.Count)
183	                {
184	                    return false;
185	                }
186	
187	                var groupColumnName = filteredArgs[index + 1];
188	                var aggregateName = filteredArgs[index + 2];
189	
190	                if (IsCommand(aggregateName, "count"))
191	                {
192	                    commands.Add(new PipelineCommand(PipelineCommandKind.GroupByCount, groupColumnName));
193	                    index += 3;
194	                    continue;
195	                }
196	
197	                if (IsCommand(aggregateName, "sum"))
198	                {
199	                    if (index + 3 >= filteredArgs.Count)
200	                    {
201	                        return false;
202	                    }
203	
204	                    commands.Add(new PipelineCommand(PipelineCommandKind.GroupBySum, groupColumnName, filteredArgs[index + 3]));
205	                    index += 4;
206	                    continue;
207	                }
208	
209	                return false;
210	            }
211	            else
212	            {
213	                return false;
214	            }
215	        }
216	
217	        return commands.Count > 0;
218	    }
