220	    private static void ExecuteCommandSequence(string path, IReadOnlyList<PipelineCommand> commands, OutputFormat format, Stream outputStream)
221	    {
222	        PipelineResult current = new TableResult(ReadTable(path));
223	
224	        foreach (var command in commands)
225	        {
226	            current = current switch
227	            {
228	                TableResult tableResult => ExecuteTableCommand(tableResult.Table, command),
229	                ScalarResult => throw new InvalidOperationException("Cannot apply a row-based command after an aggregate result"),
230	                _ => throw new ArgumentOutOfRangeException()
231	            };
232	        }
233	
234	        switch (current)
235	        {
236	            case TableResult tableResult:
237	                WriteTable(tableResult.Table, format, outputStream);
238	                break;
239	            case ScalarResult scalarResult:
240	                WriteScalar(scalarResult.Value, format, outputStream);
241	                break;
242	            default:
243	                throw new ArgumentOutOfRangeException(nameof(current));
244	        }
245	    }
