372	    private static CsvTable ReadTable(string path)
373	    {
374	        using var reader = new StreamReader(File.OpenRead(path));
375	
376	        var headerLine = reader.ReadLine() ?? throw new InvalidOperationException("CSV file is empty");
377	        var headers = ParseCsvLine(headerLine);
378	        var rows = new List<string[]>();
379	
380	        string? line;
381	        while ((line = reader.ReadLine()) is not null)
382	        {
383	            if (line.Length == 0)
384	            {
385	                continue;
386	            }
387	
388	            var values = ParseCsvLine(line);
389	            var normalized = new string[headers.Count];
390	            for (var i = 0; i < normalized.Length; i++)
391	            {
392	                normalized[i] = i < values.Count ? values[i] : string.Empty;
393	            }
394	
395	            rows.Add(normalized);
396	        }
397	
398	        return new CsvTable(headers, rows);
399	    }
