401	    private static void WriteTable(CsvTable table, OutputFormat format, Stream outputStream)
402	    {
403	        using var writer = new StreamWriter(outputStream, leaveOpen: true)
404	        {
405	            NewLine = Environment.NewLine
406	        };
407	
408	        switch (format)
409	        {
410	            case OutputFormat.Csv:
411	                writer.WriteLine(string.Join(",", table.Headers));
412	                foreach (var row in table.Rows)
413	                {
414	                    writer.WriteLine(string.Join(",", row));
415	                }
416	
417	                break;
418	            case OutputFormat.Json:
419	            {
420	                var rows = new JsonArray();
421	                foreach (var row in table.Rows)
422	                {
423	                    var obj = new JsonObject();
424	                    for (var i = 0; i < table.Headers.Count; i++)
425	                    {
426	                        obj[table.Headers[i]] = GetValue(row, i);
427	                    }
428	
429	                    rows.Add(obj);
430	                }
431	
432	                writer.WriteLine(rows.ToJsonString(new JsonSerializerOptions { WriteIndented = false }));
433	                break;
434	            }
435	            case OutputFormat.Table:
436	            {
437	                var widths = new int[table.Headers.Count];
438	                for (var i = 0; i < table.Headers.Count; i++)
439	                {
440	                    widths[i] = table.Headers[i].Length;
441	                }
442	
443	                foreach (var row in table.Rows)
444	                {
445	                    for (var i = 0; i < table.Headers.Count; i++)
446	                    {
447	                        widths[i] = Math.Max(widths[i], GetValue(row, i).Length);
448	                    }
449	                }
450	
451	                writer.WriteLine(string.Join(" | ", table.Headers.Select((header, index) => header.PadRight(widths[index]))));
452	                writer.WriteLine(string.Join(" | ", widths.Select(width => new string('-', width))));
453	                foreach (var row in table.Rows)
454	                {
455	                    writer.WriteLine(string.Join(" | ", table.Headers.Select((_, index) => GetValue(row, index).PadRight(widths[index]))));
456	                }
457	
458	                break;
459	            }
460	            default:
461	                throw new ArgumentOutOfRangeException(nameof(format), format, null);
462	        }
463	
464	        writer.Flush();
465	    }
