542	    private static CsvTable SortRows(CsvTable table, string columnName, string direction)
543	    {
544	        var descending = ParseSortDirection(direction);
545	        var headerIndexes = BuildHeaderIndex(table.Headers);
546	        if (!headerIndexes.TryGetValue(columnName, out var sortColumnIndex))
547	        {
548	            throw new InvalidOperationException($"Column not found: {columnName}");
549	        }
550	
551	        var rows = new List<SortableRow>();
552	        var rowIndex = 0;
553	        var allNumeric = true;
554	        foreach (var row in table.Rows)
555	        {
556	            var sortValue = GetValue(row, sortColumnIndex);
557	            if (!TryParseNumber(sortValue, out var numericSortValue))
558	            {
559	                allNumeric = false;
560	            }
561	
562	            rows.Add(new SortableRow(row, sortValue, numericSortValue, rowIndex++));
563	        }
564	
565	        IEnumerable<SortableRow> orderedRows = allNumeric
566	            ? descending
567	                ? rows.OrderByDescending(row => row.NumericSortValue).ThenBy(row => row.OriginalIndex)
568	                : rows.OrderBy(row => row.NumericSortValue).ThenBy(row => row.OriginalIndex)
569	            : descending
570	                ? rows.OrderByDescending(row => row.SortValue, StringComparer.Ordinal).ThenBy(row => row.OriginalIndex)
571	                : rows.OrderBy(row => row.SortValue, StringComparer.Ordinal).ThenBy(row => row.OriginalIndex);
572	
573	        return new CsvTable(new List<string>(table.Headers), orderedRows.Select(row => row.Values).ToList());
574	    }
