587	    {
588	        var distinctColumns = columnsExpression
589	            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
590	        if (distinctColumns.Length == 0)
591	        {
592	            throw new InvalidOperationException("At least one column must be specified");
593	        }
594	
595	        var headerIndexes = BuildHeaderIndex(table.Headers);
596	        var distinctIndexes = distinctColumns
597	            .Select(columnName => headerIndexes.TryGetValue(columnName, out var index)
598	                ? index
599	                : throw new InvalidOperationException($"Column not found: {columnName}"))
600	            .ToArray();
601	
602	        var rows = new List<string[]>(table.Rows.Count);
603	        var seenKeys = new HashSet<string[]>(new StringArrayComparer());
604	        foreach (var row in table.Rows)
605	        {
606	            var projected = distinctIndexes.Select(index => GetValue(row, index)).ToArray();
607	            if (seenKeys.Add(projected))
608	            {
609	                rows.Add(projected);
610	            }
611	        }
612	
613	        return new CsvTable(distinctColumns.ToList(), rows);
614	    }
